import numpy as np
import pandas as pd


def generate_signals(df):
    close = df["close"]
    change = close.diff()
    avg_gain = change.clip(lower=0).ewm(alpha=1 / 16, adjust=False, min_periods=16).mean()
    avg_loss = (-change).clip(lower=0).ewm(alpha=1 / 16, adjust=False, min_periods=16).mean()
    osc = 100 - 100 / (1 + avg_gain / avg_loss)
    osc = osc.where(avg_loss != 0, 100.0).where(avg_gain.notna())
    o = osc.to_numpy()

    pos = np.zeros(len(df), dtype=int)
    state = 0
    for t in range(len(df)):
        if np.isnan(o[t]):
            state = 0
        elif state == 0:
            if o[t] < 28:
